    def format(
        self,
        *args: Union[MessageBase, Sequence[MessageBase]],
    ) -> List:
        """Format the messages for DashScope Chat API.

        In this format function, the input messages are formatted into a
        single system messages with format "{name}: {content}" for each
        message. Note this strategy maybe not suitable for all scenarios,
        and developers are encouraged to implement their own prompt
        engineering strategies.

        The following is an example:

        .. code-block:: python

            prompt = model.format(
                Msg("system", "You\'re a helpful assistant", role="system"),
                Msg("Bob", "Hi, how can I help you?", role="assistant"),
                Msg("user", "What\'s the date today?", role="user")
            )

        The prompt will be as follows:

        .. code-block:: python

            [
                {
                    "role": "system",
                    "content": "You\'re a helpful assistant",
                },
                {
                    "role": "user",
                    "content": (
                        "## Dialogue History\n"
                        "Bob: Hi, how can I help you?\n"
                        "user: What\'s the date today?\n"
                        "[Image URL]: https://example.com/sample.jpg"
                    )
                }
            ]


        Args:
            args (`Union[MessageBase, Sequence[MessageBase]]`):
                The input arguments to be formatted, where each argument
                should be a `Msg` object, or a list of `Msg` objects.
                In distribution, placeholder is also allowed.

        Returns:
            `List[dict]`:
                The formatted messages.
        """
        # TODO: This function only convert agentscope msgs into qwen
        #  messages, the re-range is executed in _preprocess_role function.

        # Attach url to content if exists
        input_msgs = []
        for msg in args:
            if hasattr(msg, "url") and msg.url is not None:
                if isinstance(msg.url, (list, tuple)):
                    url_str = " ".join(msg.url)
                else:
                    url_str = msg.url
                # Append url to content
                if isinstance(msg.content, str):
                    msg.content += f"\n[Image URL]: {url_str}"
            if isinstance(msg, MessageBase):
                input_msgs.append(msg)
            elif isinstance(msg, list) and all(isinstance(_m, MessageBase) for _m in msg):
                input_msgs.extend(msg)
            else:
                raise TypeError(f"The input should be a Msg object or a list of Msg objects, got {type(msg)}.")

        messages = []

        # record dialog history as a list of strings
        dialogue = []
        for i, unit in enumerate(input_msgs):
            if i == 0 and unit.role == "system":
                # system prompt
                messages.append(
                    {
                        "role": unit.role,
                        "content": _convert_to_str(unit.content),
                    },
                )
            else:
                # Merge all messages into a dialogue history prompt
                dialogue.append(f"{unit.name}: {_convert_to_str(unit.content)}")

        dialogue_history = "\n".join(dialogue)

        user_content_template = "## Dialogue History\n{dialogue_history}"

        messages.append(
            {
                "role": "user",
                "content": user_content_template.format(dialogue_history=dialogue_history),
            },
        )

        return messages
EOF
